export const AUTH_HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Patholy · Private owner access</title><link rel=\"stylesheet\" href=\"/owner/auth.css\"><script src=\"/owner/auth.js\" defer></script></head><body><main class=\"access-shell\"><aside class=\"access-intro\"><a class=\"wordmark\" href=\"/owner/login\"><span class=\"brand-symbol\">P</span>Patholy</a><div><p class=\"eyebrow\">PRIVATE OWNER WORKSPACE</p><h1>Control access.<br>Keep care local.</h1><p>Manage customers, licences and device seats. Patient records, results and reports are never available in this workspace.</p></div><p class=\"security-note\">Password + authenticator verification.<br>Owner access is separate from lab accounts.</p></aside><section class=\"access-card\" aria-labelledby=\"heading\"><p class=\"eyebrow\" id=\"step\">OWNER AUTHENTICATION</p><h2 id=\"heading\">Sign in</h2><p id=\"description\">Enter your password, then verify with your authenticator.</p><div id=\"notice\" role=\"status\" aria-live=\"polite\" hidden></div><form id=\"auth-form\"><div id=\"fields\"></div><button id=\"submit\" type=\"submit\">Continue</button></form><div id=\"enrollment\" hidden><p>In your authenticator app, choose “Enter a setup key”, select a time-based code and use this secret.</p><label for=\"totp-secret\">Authenticator setup secret</label><div class=\"secret-row\"><input id=\"totp-secret\" type=\"password\" readonly autocomplete=\"off\"><button id=\"reveal\" class=\"secondary\" type=\"button\">Show</button><button id=\"copy\" class=\"secondary\" type=\"button\">Copy</button></div><p class=\"hint\">Store this secret securely. It is cleared from this page after verification.</p></div><section id=\"backup-actions\" hidden><h3>Independent recovery authenticator</h3><p>Keep the verified recovery secret on an independent secure device. Replacement requires your password and primary authenticator; pending cleanup must be completed before owner access resumes.</p><button id=\"manage-backup\" class=\"secondary\" type=\"button\">Enroll recovery authenticator</button></section><div class=\"secondary-actions\"><button id=\"restart\" class=\"text-button\" type=\"button\" hidden>Start sign-in again</button><button id=\"recovery\" class=\"text-button\" type=\"button\">Lost your authenticator or password?</button><a id=\"back-console\" href=\"/owner\" hidden>Return to owner console</a></div><p class=\"footer-note\">No default password. No password is requested through chat.</p></section></main><dialog id=\"recovery-dialog\" aria-labelledby=\"recovery-title\"><h2 id=\"recovery-title\">Recover owner access</h2><p>Recovery requires your current owner password, a previously verified independent recovery authenticator, and a private one-use maintenance link issued by the authenticated deployment administrator. The link alone does not grant owner access.</p><p>The repair session can only replace the primary authenticator. Customer and licence data stay locked until the new primary is verified and prior sessions are revoked. Sign in again afterward. If you lost the password or both authenticators, this flow cannot recover access; no public reset or bypass account is available.</p><button id=\"close-recovery\" type=\"button\">Close</button></dialog></body></html>\r\n";
